window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e7f982c6107aaf9"]={"versions": [{"id": "FIG-8e7f982c6107aaf9", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) im Kontext des SOME/IP-Protokolls (AUTOSAR PRS SOMEIPProtocol). Das Diagramm spezifiziert das Fehler- und Kommunikationsverhalten für Request/Response-Methodenaufrufe (Remote Procedure Calls) unter der Zuverlässigkeitssemantik „Maybe“ (typischerweise abgebildet über ein unzuverlässiges Transportprotokoll wie UDP). Dargestellt sind zwei getrennte, parallele Zustandsautomaten für die Rollen Client und Server.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Client</strong>: Zustandshaltende Entität der anfragenden Kommunikationsinstanz.\n<ul class=\"fig-list\"><li>Startzustand (Initial State): Ausgefüllter schwarzer Kreis.\n</li><li><code>waitingForResponse</code>: Zustand, in dem der Client auf die Antwortnachricht des Servers wartet.\n</li><li><code>Error: NoResponse</code>: Fehlerzustand bei Ausbleiben der Antwort nach Ablauf des Timeouts.\n</li><li>Endzustand (Final State): Umrandeter schwarzer Kreis.\n</li></ul>\n</li><li><strong>Server</strong>: Zustandshaltende Entität der dienstanbietenden Instanz.\n<ul class=\"fig-list\"><li>Startzustand (Initial State): Ausgefüllter schwarzer Kreis.\n</li><li><code>processing</code>: Zustand, in dem der Server die eingehende Anfrage verarbeitet.\n</li><li>Endzustand (Final State): Umrandeter schwarzer Kreis.\n</li></ul>\n</li><li><strong>Ereignisse und Aktionen</strong>:\n<ul class=\"fig-list\"><li><code>/ sendReq</code>: Aktion zum Senden der Request-Nachricht beim Übergang aus dem Initialzustand.\n</li><li><code>rspReceived</code>: Trigger-Ereignis bei Empfang der Antwortnachricht.\n</li><li><code>rspTimeout</code>: Trigger-Ereignis bei Ablauf des Antwort-Timers.\n</li><li><code>reqReceived</code>: Trigger-Ereignis bei Eingang der Request-Nachricht auf Serverseite.\n</li><li><code>/ sendRsp</code>: Aktion zum Versenden der Antwortnachricht beim Übergang in den Endzustand.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Client-Ablauf</strong>:\n<ol class=\"fig-list\"><li>Ausgehend vom Startzustand sendet der Client die Anfrage (<code>/ sendReq</code>) und wechselt unmittelbar in den Zustand <code>waitingForResponse</code>.\n</li><li>Trifft die Serverantwort rechtzeitig ein (<code>rspReceived</code>), erfolgt ein direkter Zustandsübergang in den Endzustand.\n</li><li>Läuft die konfigurierte Wartezeit ab, ohne dass eine Antwort empfangen wurde (<code>rspTimeout</code>), wechselt der Client in den Fehlerzustand <code>Error: NoResponse</code>.\n</li><li>Aus <code>Error: NoResponse</code> geht der Automat in den Endzustand über.\n</li></ol>\n</li><li><strong>Server-Ablauf</strong>:\n<ol class=\"fig-list\"><li>Bei Empfang einer Anfragenachricht (<code>reqReceived</code>) geht der Server vom Startzustand in den Zustand <code>processing</code> über.\n</li><li>Nach Abschluss der Verarbeitung sendet der Server die Antwortnachricht (<code>/ sendRsp</code>) und wechselt damit in den Endzustand.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ für die Implementierung der SOME/IP-RPC-Kommunikation über UDP nach dem „Maybe“-Zuverlässigkeitsmodell.\n</li><li>Auf Clientseite ist genau ein einziger Timeout-Timer für die Überwachung der Antwort (<code>rspTimeout</code>) erforderlich. Bei Eintritt des Timeouts signalisiert SOME/IP der Client-Anwendung den Fehler <code>E_TIMEOUT</code>.\n</li><li>Da es sich um „Maybe“-Semantik handelt, existiert auf Protokollebene kein automatischer Wiederholungsmechanismus (kein Re-Transmission/Retry im Zustandsautomaten). Eine weitergehende Fehlerbehandlung obliegt der Anwendungsschicht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a4e48c02023945bb", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) im Kontext des SOME/IP-Protokolls (AUTOSAR PRS SOMEIPProtocol). Das Diagramm spezifiziert das Fehler- und Kommunikationsverhalten für Request/Response-Methodenaufrufe (Remote Procedure Calls) unter der Zuverlässigkeitssemantik „Maybe“ (typischerweise abgebildet über ein unzuverlässiges Transportprotokoll wie UDP). Dargestellt sind zwei getrennte, parallele Zustandsautomaten für die Rollen Client und Server.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Client</strong>: Zustandshaltende Entität der anfragenden Kommunikationsinstanz.\n<ul class=\"fig-list\"><li>Startzustand (Initial State): Ausgefüllter schwarzer Kreis.\n</li><li><code>waitingForResponse</code>: Zustand, in dem der Client auf die Antwortnachricht des Servers wartet.\n</li><li><code>Error: NoResponse</code>: Fehlerzustand bei Ausbleiben der Antwort nach Ablauf des Timeouts.\n</li><li>Endzustand (Final State): Umrandeter schwarzer Kreis.\n</li></ul>\n</li><li><strong>Server</strong>: Zustandshaltende Entität der dienstanbietenden Instanz.\n<ul class=\"fig-list\"><li>Startzustand (Initial State): Ausgefüllter schwarzer Kreis.\n</li><li><code>processing</code>: Zustand, in dem der Server die eingehende Anfrage verarbeitet.\n</li><li>Endzustand (Final State): Umrandeter schwarzer Kreis.\n</li></ul>\n</li><li><strong>Ereignisse und Aktionen</strong>:\n<ul class=\"fig-list\"><li><code>/ sendReq</code>: Aktion zum Senden der Request-Nachricht beim Übergang aus dem Initialzustand.\n</li><li><code>rspReceived</code>: Trigger-Ereignis bei Empfang der Antwortnachricht.\n</li><li><code>rspTimeout</code>: Trigger-Ereignis bei Ablauf des Antwort-Timers.\n</li><li><code>reqReceived</code>: Trigger-Ereignis bei Eingang der Request-Nachricht auf Serverseite.\n</li><li><code>/ sendRsp</code>: Aktion zum Versenden der Antwortnachricht beim Übergang in den Endzustand.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Client-Ablauf</strong>:\n<ol class=\"fig-list\"><li>Ausgehend vom Startzustand sendet der Client die Anfrage (<code>/ sendReq</code>) und wechselt unmittelbar in den Zustand <code>waitingForResponse</code>.\n</li><li>Trifft die Serverantwort rechtzeitig ein (<code>rspReceived</code>), erfolgt ein direkter Zustandsübergang in den Endzustand.\n</li><li>Läuft die konfigurierte Wartezeit ab, ohne dass eine Antwort empfangen wurde (<code>rspTimeout</code>), wechselt der Client in den Fehlerzustand <code>Error: NoResponse</code>.\n</li><li>Aus <code>Error: NoResponse</code> geht der Automat in den Endzustand über.\n</li></ol>\n</li><li><strong>Server-Ablauf</strong>:\n<ol class=\"fig-list\"><li>Bei Empfang einer Anfragenachricht (<code>reqReceived</code>) geht der Server vom Startzustand in den Zustand <code>processing</code> über.\n</li><li>Nach Abschluss der Verarbeitung sendet der Server die Antwortnachricht (<code>/ sendRsp</code>) und wechselt damit in den Endzustand.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ für die Implementierung der SOME/IP-RPC-Kommunikation über UDP nach dem „Maybe“-Zuverlässigkeitsmodell.\n</li><li>Auf Clientseite ist genau ein einziger Timeout-Timer für die Überwachung der Antwort (<code>rspTimeout</code>) erforderlich. Bei Eintritt des Timeouts signalisiert SOME/IP der Client-Anwendung den Fehler <code>E_TIMEOUT</code>.\n</li><li>Da es sich um „Maybe“-Semantik handelt, existiert auf Protokollebene kein automatischer Wiederholungsmechanismus (kein Re-Transmission/Retry im Zustandsautomaten). Eine weitergehende Fehlerbehandlung obliegt der Anwendungsschicht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8e7f982c6107aaf9", "to": "FIG-a4e48c02023945bb", "fr": "R17-10_R1.2.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
